<script lang="ts">
  import { Progress } from "bits-ui";
  import { RefreshCw } from "@lucide/svelte";
  import { effectiveLocale, formatDateTime, formatNumber, t } from "$lib/i18n/index.svelte";
  import { DEVELOPMENT_VERSION } from "$lib/updater/api";
  import { updateStore } from "$lib/updater/store.svelte";
  import type { Settings } from "./api";
  import ReleaseNotes from "./ReleaseNotes.svelte";

  let { settings = $bindable(), onchecked, onerror, heading = $bindable() }: { settings: Settings; onchecked: () => Promise<void>; onerror: (message: string) => void; heading?: HTMLHeadingElement } = $props();
  const appVersion = $derived(updateStore.appVersion), update = $derived(updateStore.update), phase = $derived(updateStore.phase), progress = $derived(updateStore.progress), busy = $derived(updateStore.busy);
  const progressLabel = $derived(progress === null ? t("settings.downloading") : `${formatNumber(progress)}%`);
  const lastChecked = $derived(settings.last_update_check ? t("settings.lastChecked", { time: formatDateTime(settings.last_update_check) }) : t("settings.notChecked"));
  const message = $derived.by(() => {
    effectiveLocale();
    switch (phase) {
      case "checking": return updateStore.displayStatus === "current" ? t("settings.updateCurrent") : updateStore.displayStatus === "available" && update ? t("settings.newVersion", { version: update.version }) : updateStore.displayStatus === "skipped" ? t("settings.skippedVersion", { version: updateStore.skippedVersion ?? "" }) : t("settings.checkingLong");
      case "current": return t("settings.updateCurrent"); case "skipped": return t("settings.skippedVersion", { version: updateStore.skippedVersion ?? "" });
      case "downloading": return t("settings.downloadingVersion", { version: update?.version ?? "" }); case "downloaded": return t("settings.downloadedVersion", { version: update?.version ?? "" }); case "installing": return t("settings.installing");
      case "error": return updateStore.errorSource === "unsupported" ? t("settings.devUpdate") : updateStore.errorSource === "install" ? t("settings.installFailedTitle") : updateStore.errorSource === "relaunch" ? t("settings.restartFailedTitle") : updateStore.errorSource === "download" ? t("settings.downloadFailedTitle") : t("settings.checkFailedTitle");
      default: return update ? t("settings.newVersion", { version: update.version }) : t("settings.notChecked");
    }
  });
  const detail = $derived(phase === "checking" && updateStore.displayStatus ? t("settings.checkingLong") : phase === "current" ? lastChecked : phase !== "error" ? "" : updateStore.errorSource === "download" || updateStore.errorSource === "check" ? t("settings.checkConnection") : updateStore.errorSource === "install" ? t("settings.packageRetained") : updateStore.errorSource === "relaunch" ? t("settings.updateInstalled") : "");
  function version(value: string) { return value === DEVELOPMENT_VERSION ? t("update.devVersion") : value === "__clipclop_unknown__" ? t("common.unknown") : value; }
</script>

<div class="updates-layout"><h1 bind:this={heading} id="settings-section-title" tabindex="-1">{t("settings.updates")}</h1><section class="update-section" aria-label={t("settings.updateSettingsAndStatus")}><div class="update-head"><span><strong>{t("settings.autoCheckUpdates")}</strong><small>{t("settings.currentVersion", { version: version(appVersion) })}</small></span><div class="update-head-controls"><button class="update-refresh" disabled={phase === "checking" || busy} aria-label={t("settings.check")} title={t("settings.check")} aria-busy={phase === "checking"} onclick={onchecked}><RefreshCw size={15} class={phase === "checking" ? "spin" : ""} /></button><label class="switch"><input type="checkbox" role="switch" aria-label={t("settings.autoCheckUpdates")} bind:checked={settings.check_updates} /><span class="switch-track"></span></label></div></div><div class="update-rail"><span class="visually-hidden" role={phase === "error" ? "alert" : "status"} aria-live="polite">{message}{detail ? ` ${detail}` : ""}</span><div class="update-rail-main"><strong class:error={phase === "error" && updateStore.errorSource !== "unsupported"}>{message}</strong>{#if phase === "downloading"}<div class="update-progress"><Progress.Root class="progress-track" value={progress} max={100} aria-label={progressLabel} aria-valuetext={progressLabel}><div class="progress-fill" class:indeterminate={progress === null} style={progress === null ? "" : `width:${progress}%`}></div></Progress.Root>{#if progress !== null}<span class="progress-label">{formatNumber(progress)}%</span>{/if}</div>{:else if detail}<span class="update-detail">{detail}</span>{/if}</div><div class="update-actions">{#if phase === "downloading"}<button class="update-primary" onclick={() => void updateStore.cancel()}>{t("common.cancel")}</button>{:else if phase === "downloaded"}<button class="secondary" onclick={() => void updateStore.skip()}>{t("settings.skipVersion")}</button><button class="update-primary" onclick={() => void updateStore.install()}>{t("settings.installRestart")}</button>{:else if phase === "error" && updateStore.errorSource === "relaunch"}<button class="update-primary" onclick={() => void updateStore.retry()}>{t("settings.restart")}</button>{:else if phase === "error" && (updateStore.errorSource === "download" || updateStore.errorSource === "install")}<button class="secondary" onclick={() => void updateStore.skip()}>{t("settings.skipVersion")}</button><button class="update-primary" onclick={() => void updateStore.retry()}>{t("settings.retry")}</button>{:else if phase === "error" && updateStore.errorSource === "check"}<button class="update-primary" onclick={() => void updateStore.retry()}>{t("settings.retry")}</button>{:else if update && phase !== "installing" && phase !== "checking"}<button class="secondary" onclick={() => void updateStore.skip()}>{t("settings.skipVersion")}</button><button class="update-primary" onclick={() => void updateStore.download()}>{t("settings.download")}</button>{/if}</div></div></section><ReleaseNotes updateVersion={update?.version} {onerror} /></div>

<style>
  .updates-layout{height:100%;min-height:0;display:flex;flex-direction:column}h1{margin:18px 0 4px;font-size:var(--fs-heading);font-weight:680;line-height:1.3;letter-spacing:-.01em}h1:focus{outline:none}.update-section{flex:none}.update-head{min-height:68px;padding-block:12px;display:flex;align-items:center;justify-content:space-between;gap:24px;border-bottom:1px solid var(--hairline)}.update-head>span{flex:1 1 auto;min-width:0;display:flex;flex-direction:column;gap:3px}.update-head-controls{flex:none;display:flex;align-items:center;gap:8px}.update-refresh{position:relative;width:32px;height:32px;padding:0;display:grid;place-items:center}.update-refresh :global(svg.spin){animation:spin 1s linear infinite}.update-rail{height:56px;display:flex;align-items:center;justify-content:space-between;gap:18px;border-bottom:1px solid var(--hairline)}.update-rail-main{min-width:0;flex:1;display:flex;align-items:center;gap:12px}.update-rail-main>strong{min-width:0;max-width:210px;flex:0 1 auto;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.update-detail{min-width:0;overflow:hidden;color:var(--text-2);font-size:var(--fs-ui);text-overflow:ellipsis;white-space:nowrap}.update-progress{min-width:80px;flex:1;display:flex;align-items:center;gap:8px}.update-progress :global(.progress-track){min-width:80px;flex:1;height:4px;overflow:hidden;border-radius:var(--radius-pill);background:var(--bg-selected)}.progress-fill{height:100%;border-radius:var(--radius-pill);background:var(--action);transition:width var(--dur-slow) ease}.progress-fill.indeterminate{width:35%;animation:progress-slide 1.1s ease-in-out infinite}.progress-label{width:38px;flex:none;color:var(--text-2);font-size:var(--fs-ui);font-variant-numeric:tabular-nums;text-align:right}.update-actions{flex:none;display:flex;align-items:center;gap:8px}.update-actions button{min-height:32px;padding:0 12px;white-space:nowrap}.update-primary{min-width:88px;color:var(--action-on);background:var(--action);font-weight:600}.update-primary:hover{color:var(--action-on);background:var(--action-hover)}.secondary{color:var(--text-3)}button{border:0;border-radius:var(--radius-md);color:var(--text-2);background:transparent;font-size:var(--fs-ui)}button:hover{color:var(--text-1);background:var(--bg-hover)}button:focus-visible{outline:2px solid var(--text-1);outline-offset:2px}button:disabled{opacity:.45;cursor:not-allowed}.switch{position:relative;flex:none;width:44px;height:44px;cursor:pointer}.switch input{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip:rect(0,0,0,0);clip-path:inset(50%);white-space:nowrap}.switch-track{position:absolute;left:4px;top:12px;width:36px;height:20px;border:1px solid color-mix(in srgb,var(--text-2) 42%,var(--bg-selected));border-radius:var(--radius-pill);background:var(--bg-selected);transition:background var(--dur-fast) ease-out,border-color var(--dur-fast) ease-out}.switch-track:after{content:"";position:absolute;left:1px;top:1px;width:16px;height:16px;border-radius:50%;background:#fff;box-shadow:0 1px 3px rgba(0,0,0,.22);transition:transform var(--dur-fast) ease-out}.switch input:checked+.switch-track{border-color:var(--action);background:var(--action)}.switch input:checked+.switch-track:after{transform:translateX(16px);background:var(--action-on)}.switch input:focus-visible+.switch-track{outline:2px solid var(--text-2);outline-offset:3px}.switch:hover .switch-track{border-color:var(--text-2)}.switch:hover input:checked+.switch-track{border-color:var(--action)}.visually-hidden{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}.error{color:var(--danger)}strong{font-size:var(--fs-body)}small{color:var(--text-3);font-size:var(--fs-ui);line-height:1.4}@keyframes spin{to{transform:rotate(360deg)}}@keyframes progress-slide{0%{transform:translateX(-120%)}100%{transform:translateX(340%)}}@media(prefers-reduced-motion:reduce){.progress-fill.indeterminate,.update-refresh :global(svg.spin){animation:none}.switch-track,.switch-track:after{transition:none}}@media(forced-colors:active){.switch-track{border:1px solid ButtonText;background:Canvas}.switch-track:after{background:ButtonText}.switch input:checked+.switch-track{background:Highlight}.switch input:checked+.switch-track:after{background:HighlightText}}
</style>
